        "Należy do przyimków zmiennych: na pytanie Wo? (gdzie?) łączy się z celownikiem (an der Tür), na pytanie Wohin? (dokąd?) — z biernikiem (an die Tür). Formy ściągnięte: an dem → am, an das → ans.",
        "W odniesieniu do czasu używa się go z dniami i porami dnia: am Montag, am Abend. Wiele czasowników wymaga an + biernik: an dich denken (myśleć o tobie)."
