        "Der pojawia się też w innych przypadkach: w rodzaju żeńskim w celowniku i dopełniaczu (der Frau) oraz przy wszystkich rzeczownikach w liczbie mnogiej w dopełniaczu (die Autos der Eltern). W rodzaju męskim biernik to den, celownik dem, dopełniacz des.",
