      "translation": "znaleźć • uważać",
      "explanation": [
        "Główna myśl: finden znaczy znaleźć (Ich finde meinen Schlüssel nicht) oraz wyrażać opinię — uważać, myśleć: Ich finde den Film gut, Ich finde, dass das eine gute Idee ist.",
        "Formy: er findet, fand, hat gefunden. W znaczeniu opinii finden wymaga biernika i przymiotnika: den Film gut finden (uważać film za dobry).",
        "Finden znaczy znaleźć coś konkretnego lub przypadkiem; samo szukanie to suchen."
      ],
      "examples": [
        {
          "de": "Ich finde meinen Schlüssel nicht.",
          "lv": "Nie mogę znaleźć swojego klucza."
        },
        {
          "de": "Wie findest du den Film?",
          "lv": "Co myślisz o tym filmie?"
        },
        {
          "de": "Ich finde das Essen lecker.",
          "lv": "Uważam, że jedzenie jest smaczne."
        },
        {
          "de": "Ich finde, das ist eine gute Idee.",
          "lv": "Myślę, że to dobry pomysł."
        },
        {
          "de": "Wir haben ein Hotel gefunden.",
          "lv": "Znaleźliśmy hotel."
        }
      ],
      "comparison": [
        {
          "word": "suchen",
          "meaning": "szukać",
          "example": "Ich suche meinen Schlüssel. – Szukam swojego klucza."
        },
        {
          "word": "denken",
          "meaning": "myśleć",
          "example": "Ich denke an dich. – Myślę o tobie."
        },
        {
          "word": "glauben",
          "meaning": "wierzyć, sądzić",
          "example": "Ich glaube, er kommt. – Sądzę, że on przyjdzie."
        }
      ],
      "tip": [
        "Wie findest du …? to codzienne pytanie o opinię.",
        "W zdaniu wyrażającym opinię: finden + biernik + przymiotnik."
      ],
      "important": [
        "Gefunden to poprawny imiesłów; nie „gefindet”.",
        "Finden ≠ suchen: szuka się za pomocą suchen, a znajduje za pomocą finden."
      ],
