        "Formy: ich mag, du magst, er/sie/es mag, wir mögen, ihr mögt, sie mögen; mochte, hat gemocht. To czasownik modalny, ale często występuje samodzielnie z biernikiem.",
        "Do uprzejmej prośby używa się möchte: Ich möchte einen Kaffee — chciałbym kawę (od mögen, ale jako osobna forma)."
